class BowlingGame:
    def __init__(self):
        self.rolls = []

    def roll(self, pins):
        if pins < 0:
            raise Exception("Negative roll is invalid")
        if pins > 10:
            raise Exception("Pin count exceeds 10")
        if self._game_over():
            raise Exception("Cannot roll after game is over")
        start, _ = self._frame_bounds()[-1]
        frame = self.rolls[start:]
        if len(frame) == 1:
            if frame[0] < 10 and frame[0] + pins > 10:
                raise Exception("Pin count exceeds pins available in frame")
        elif len(frame) == 2:
            # Only possible in the tenth frame.
            if frame[0] == 10 and frame[1] < 10 and frame[1] + pins > 10:
                raise Exception("Pin count exceeds pins available in frame")
        self.rolls.append(pins)

    def score(self):
        if not self._game_over():
            raise Exception("Score cannot be determined until the game is complete")
        total = 0
        bounds = self._frame_bounds()
        for index, (start, end) in enumerate(bounds):
            if index == 9:
                total += sum(self.rolls[start:end])
            else:
                frame = self.rolls[start:end]
                if frame[0] == 10:
                    total += 10 + sum(self.rolls[end:end + 2])
                elif frame[0] + frame[1] == 10:
                    total += 10 + self.rolls[end]
                else:
                    total += frame[0] + frame[1]
        return total

    def _frame_bounds(self):
        """Return (start, end) index pairs into self.rolls, one per started frame."""
        bounds = []
        index = 0
        count = len(self.rolls)
        for frame in range(10):
            if index >= count:
                break
            if frame < 9:
                if self.rolls[index] == 10:
                    bounds.append((index, index + 1))
                    index += 1
                else:
                    bounds.append((index, min(index + 2, count)))
                    index += 2
            else:
                bounds.append((index, count))
        return bounds

    def _game_over(self):
        bounds = self._frame_bounds()
        if len(bounds) < 10:
            return False
        start, end = bounds[9]
        rolls = self.rolls[start:end]
        if len(rolls) >= 3:
            return True
        if len(rolls) == 2:
            if rolls[0] == 10:
                return rolls[1] == 10
            return rolls[0] + rolls[1] < 10
        return False

